export type Lattice = WasmDevice<typeof LATTICE_PARAMS>

/** Scale-aware harmonizer: tracks a single line and adds up to four voices on the steps of a scale, by interval or by Thesis voicing around a centre note, each with its own delay, feedback, level and pan. */
export function createLattice(
  context: BaseAudioContext,
  options: WasmDeviceOptions<typeof LATTICE_PARAMS> = {},
): Promise<Lattice> {
  return WasmDevice.create(context, LATTICE_DEVICE, options)
}
